import{_ as u,a0 as r,w as a,s as i,ao as l,I as p,x as o,a1 as n,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const c=JSON.parse('{"title":"如何在Ubuntu中屏蔽一个网站 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Ubuntu中屏蔽一个网站 | LCTT (201403) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Ubuntu中屏蔽一个网站 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Ubuntu中屏蔽一个网站 | LCTT (201403) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201403/How To Block A Website In Ubuntu","title":"如何在Ubuntu中屏蔽一个网站","tag":"201403","desc":""},"relativePath":"201403/How To Block A Website In Ubuntu.md","filePath":"[post].md"}'),b={name:"201403/How To Block A Website In Ubuntu.md"};function m(d,t,T,g,f,x){const e=r("Link");return a(),i("div",null,[t[11]||(t[11]=l(`<h1 id="如何在ubuntu中屏蔽一个网站" tabindex="-1">如何在Ubuntu中屏蔽一个网站 <a class="header-anchor" href="#如何在ubuntu中屏蔽一个网站" aria-label="Permalink to “如何在Ubuntu中屏蔽一个网站”">​</a></h1><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/02/block-websites.jpg" alt=""></p><p>亲爱的<strong>ubuntu</strong>极客们，</p><p>在本教程中我将教你如何通过编辑<strong>/etc/hosts</strong>文件来屏蔽在Ubuntu Linux上不受欢迎的网站，这是用来处理DNS和Linux网络的系统文件。</p><p>我很喜欢这种方法，因为我不需要依靠第三方应用程序，这是非常容易使用的。您需要做的就是在<strong>/etc/hosts文件</strong>文件中做一个简单的变化。</p><p>请确保您有使用此方法时在机器上处于root用户访问状态，因为<strong>/etc/hosts文件</strong>文件由root用户拥有的，所以它不能被不被普通用户编辑。</p><p>编辑 <strong>/etc/hosts</strong> 文件您需要什么？root权限和一个文本编辑器。</p><p>在本教程中我将用我喜欢的文本编辑器，vim。好了，打开一个新的终端（<strong>CTRL+ALT+T</strong>），然后运行下面的命令来打开/etc/hosts文件进行编辑。</p><pre><code>vim /etc/hosts
</code></pre><p>添加下面这行</p><pre><code>127.0.0.1   domain.com
</code></pre><p>更换domain.com为你要屏蔽的网站，你完成了编辑处理后，保存该文件并退出。</p><p>现在是时候来测试该方法是否成功了。尝试访问你屏蔽的网站。</p><p>我的表弟是沉迷于Facebook的社交网络，每次他发现我的笔记本电脑的时候，他就打开它，并去facebook.com陪陪他的朋友。</p><p>我应该怎么做呢？</p><p>我编辑<strong>/etc/hosts</strong>文件，这样他想访问的网站就像已关闭了一样。</p><p>您也可以使用这个方法来保护孩子免受互联网成人内容的危害，如色情和恐怖电影。</p><hr>`,18)),p("p",null,[t[1]||(t[1]=o("via: ",-1)),n(e,{href:"http://www.unixmen.com/block-website-ubuntu/"},{default:s(()=>[...t[0]||(t[0]=[o("http://www.unixmen.com/block-website-ubuntu/",-1)])]),_:1})]),p("p",null,[t[4]||(t[4]=o("译者：",-1)),n(e,{href:"https://github.com/yechunxiao19"},{default:s(()=>[...t[2]||(t[2]=[o("乌龙茶",-1)])]),_:1}),t[5]||(t[5]=o(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:s(()=>[...t[3]||(t[3]=[o("wxy",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=o("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[6]||(t[6]=[o("LCTT",-1)])]),_:1}),t[9]||(t[9]=o(" 原创翻译，",-1)),n(e,{href:"http://linux.cn/"},{default:s(()=>[...t[7]||(t[7]=[o("Linux中国",-1)])]),_:1}),t[10]||(t[10]=o(" 荣誉推出",-1))])])}const k=u(b,[["render",m]]);export{c as __pageData,k as default};
